mapper.update:
update service_bookings

      scheduled_date = #{serviceBooking.scheduledDate},
      status = #{serviceBooking.status},
      notes = #{serviceBooking.notes},
      updated_at = #{serviceBooking.updatedAt}

where id = #{serviceBooking.id}

mapper.select:
select id, user_id, vehicle_id, service_type_id, scheduled_date, status, notes, created_at, updated_at
from service_bookings where user_id = #{userId}
order by scheduled_date desc

select id, user_id, vehicle_id, service_type_id, scheduled_date, status, notes, created_at, updated_at
from service_bookings where vehicle_id = #{vehicleId}
order by scheduled_date desc

select id, user_id, vehicle_id, service_type_id, scheduled_date, status, notes, created_at, updated_at
from service_bookings where status = #{status}
order by scheduled_date desc
